import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline

fused_cpp_source = """
torch::Tensor fused_min_add_mul_cuda(torch::Tensor x, torch::Tensor bias, float cval, float scaling_factor);
"""

fused_cuda_source = r"""
#include <torch/extension.h>
__global__ void fused_min_add_mul_kernel(
    const float* __restrict__ in,
    float* __restrict__ out,
    const float* __restrict__ bias,
    float cval,
    float scaling_factor,
    int B, int O, int H, int W
) {
    int idx = blockIdx.x * blockDim.x + threadIdx.x;
    int total_size = B * O * H * W;
    if (idx < total_size) {
        float val = in[idx];
        if (val > cval) {
            val = cval;
        }
        int o = (idx / (H * W)) % O;
        val += bias[o];
        val *= scaling_factor;
        out[idx] = val;
    }
}

torch::Tensor fused_min_add_mul_cuda(
    torch::Tensor x,
    torch::Tensor bias,
    float cval,
    float scaling_factor
) {
    auto sizes = x.sizes();
    int B = sizes[0];
    int O = sizes[1];
    int H = sizes[2];
    int W = sizes[3];

    auto out = torch::empty_like(x);
    int total_size = B * O * H * W;

    int threads = 256;
    int blocks = (total_size + threads - 1) / threads;

    fused_min_add_mul_kernel<<<blocks, threads>>>(
        x.data_ptr<float>(),
        out.data_ptr<float>(),
        bias.data_ptr<float>(),
        cval,
        scaling_factor,
        B, O, H, W
    );

    return out;
}
"""

fused_ops = load_inline(
    name="fused_ops",
    cpp_sources=fused_cpp_source,
    cuda_sources=fused_cuda_source,
    functions=["fused_min_add_mul_cuda"],
    verbose=False,
)

class ModelNew(nn.Module):
    """
    Optimized model that uses a custom CUDA kernel to fuse min, bias addition, and scaling operations.
    """
    def __init__(self, in_channels, out_channels, kernel_size, constant_value, bias_shape, scaling_factor):
        super(ModelNew, self).__init__()
        self.conv = nn.Conv2d(in_channels, out_channels, kernel_size)
        self.constant_value = constant_value
        self.bias = nn.Parameter(torch.randn(bias_shape))
        self.scaling_factor = scaling_factor
        self.fused_ops = fused_ops

    def forward(self, x):
        x = self.conv(x)
        # Flatten the bias to match channel dimension, pass to the fused CUDA kernel
        x = self.fused_ops.fused_min_add_mul_cuda(
            x, self.bias.view(-1), self.constant_value, self.scaling_factor
        )
        return x

